-- Gerente inicial: troque o e-mail pelo da conta criada em Authentication
insert into public.fs_docs (col, id, data)
select 'users', u.id::text, jsonb_build_object('name', 'Gerente', 'email', u.email, 'role', 'gerente',
       'perms', '[]'::jsonb, 'active', true, 'createdAt', to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
  from auth.users u
 where u.email = 'karchtzn@gmail.com'
on conflict (col, id) do nothing;
